mapper.insert:
INSERT  /* SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbseumListMapper.insertBbseum : 이음게시판 등록 */
INTO    
        AYE100 
(
        BBSCTT_ESNTAL_NO    /*게시글번호*/
    ,   BBSCTT_TYPE_SE_CD   /*게시글코드*/
    ,   BBSCTT_TTL_NM       /*게시글제목*/
    ,   BBSCTT_CN           /*게시글내용*/
    ,   WRTR_NM_ENCPT             /*작성자명*/
    ,   BRTH_YMD            /*출생년도*/
    ,   ATFINO              /*첨부파일명*/
    ,   CNTN_IP_ADDR        /*아이피*/
    ,   EML_ADDR_ENCPT            /*이메일*/
    ,   HPGE_URL_ADDR       /*홈페이지*/
    ,   SXDC_SE_CD          /*성별구분코드*/
    ,   NTABRD_PSWD_ENCPT        /*글비번*/
    ,   FRST_RGTR_ID    
    ,   FRST_REG_DT
    ,   LAST_MDFR_ID
    ,   LAST_MDFCN_DT
)
VALUES
(
        (
        SELECT 
            NVL(MAX(BBSCTT_ESNTAL_NO),0) +1     
        FROM 
            AYE100
        WHERE 
            BBSCTT_TYPE_SE_CD = '03'   /*게시글구분코드*/
        )  
    ,   '03'               /*게시글구분코드*/
    ,   #{BBSCTT_TTL_NM}
    ,   #{BBSCTT_CN}
    ,   #{WRTR_NM_ENCPT}
    ,   #{BRTH_YR}
    ,   #{ATFINO}
    ,   #{CNTN_IP_ADDR}
    ,   #{EML_ADDR_ENCPT}
    ,   #{HPGE_URL_ADDR}
    ,   #{SXDC_SE_CD}
    ,   #{NTABRD_PSWD_ENCPT}
    ,   #{FRST_RGTR_ID}
    ,   SYSDATE
    ,   #{LAST_MDFR_ID}
    ,   SYSDATE 
)

mapper.update:
	UPDATE  /* SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbseumListMapper.updateBbseum : 이음게시판 수정 */
	        AYE100  
	SET
	        BBSCTT_TTL_NM          =       #{BBSCTT_TTL_NM}
	    ,   BBSCTT_CN              =       #{BBSCTT_CN}
	    ,   CNSLTNT_NM_ENCPT       =       #{CNSLTNT_NM_ENCPT}
	    ,   EML_ADDR_ENCPT         =       #{EML_ADDR_ENCPT}
	    ,   BRTH_YMD               =       #{BRTH_YR}
	    ,   SXDC_SE_CD             =       #{SXDC_SE_CD}
	    ,   HPGE_URL_ADDR          =       #{HPGE_URL_ADDR}
	    ,   CRISIS_TYPE_SE_CD      =       #{CRISIS_TYPE_SE_CD}
	    ,   NTABRD_PSWD_ENCPT      =       #{NTABRD_PSWD_ENCPT}
        ,   ATFINO                 =       #{ATFINO}
	    ,   LAST_MDFCN_DT          =       SYSDATE      
	    ,   LAST_MDFR_ID           =       #{LAST_MDFR_ID}    
	WHERE   1=1
	    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
	    AND BBSCTT_TYPE_SE_CD      =       '03'                   /*  게시판유형구분코드  */

mapper.insert:
	INSERT 
	INTO    AYE120
    (
            BBSCTT_ESNTAL_NO            /*  게시글번호           */
        ,   BBSCTT_TYPE_SE_CD           /*  게시글유형구분     */
        ,   RETE_ESNTAL_NO              /*  답글고유번호      */
        ,   WRTR_NM_ENCPT               /*  작성자명            */
        ,   CNTN_IP_ADDR                /*  아이피         */
        ,   DSCSN_RELM_SE_CD            /*  상담영역구분코드        */
        ,   SXDC_SE_CD                  /*  성별구분코드      */
        ,   NTABRD_CSC_OCCP_SE_CD       /*  직업구분코드      */
        ,   ACBG_SE_CD                  /*  학력구분코드      */
        ,   GRADE_SE_CD                 /*  학년구분코드      */
        ,   PROBM_STTS_LCLAS_SE_CD      /*  문제상태대분류구분코드 */
        ,   PROBM_STTS_MLSFC_SE_CD      /*  문제상태중분류구분코드 */
        ,   PROBM_STTS_SCLAS_SE_CD      /*  문제상태소분류구분코드 */
        ,   PROBM_CAS_LCLAS_SE_CD       /*  문제원인대분류구분코드 */
        ,   PROBM_CAS_SCLAS_SE_CD       /*  문제원인소분류구분코드 */
        ,   SCHL_VIOLNC_YN              /*  학교폭력여부      */
        ,   LABOR_YN                    /*  근로여부            */
        ,   CYBER_VIOLNC_YN             /*  사이버폭력여부     */
        ,   RETE_TTL_NM                 /*  답글제목명           */
        ,   RETE_CN                     /*  답글내용            */
        ,   ISSUE_PROBM_SE_CD           /*  이슈문제구분코드        */
        ,   ETC_CN                      /*  문제상세            */
        ,   ATFINO                      /*  첨부파일번호            */
        ,   FRST_RGTR_ID
        ,   FRST_REG_DT
        ,   LAST_MDFR_ID
        ,   LAST_MDFCN_DT
    )
    VALUES(
            #{BBSCTT_ESNTAL_NO}                        /* 게시글 번호     */
        ,   '03'                                       /* 게시글유형구분 */  

        ,   AYE120_SQ01.NEXTVAL                        /* 답글번호 (이음상담게시판)   */

        ,   #{WRTR_NM_ENCPT}
        ,   #{CNTN_IP_ADDR}
        ,   #{DSCSN_RELM_SE_CD}
        ,   #{SXDC_SE_CD}
        ,   #{NTABRD_CSC_OCCP_SE_CD}
        ,   #{ACBG_SE_CD}
        ,   #{GRADE_SE_CD}
        ,   #{PROBM_STTS_LCLAS_SE_CD}
        ,   #{PROBM_STTS_MLSFC_SE_CD}
        ,   #{PROBM_STTS_SCLAS_SE_CD}
        ,   #{PROBM_CAS_LCLAS_SE_CD}
        ,   #{PROBM_CAS_SCLAS_SE_CD}
        ,   #{SCHL_VIOLNC_YN}
        ,   #{LABOR_YN}
        ,   #{CYBER_VIOLNC_YN}
        ,   #{RETE_TTL_NM}
        ,   #{RETE_CN}
        ,   #{ISSUE_PROBM_SE_CD}
        ,   #{ETC_CN}
        ,   #{ATFINO}
        ,   #{FRST_RGTR_ID}
        ,   SYSDATE 
        ,   #{LAST_MDFR_ID}
        ,   SYSDATE
	)

mapper.update:
UPDATE  
        AYE100  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO        =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD       =       '03'                   /*  게시판유형구분코드   */

UPDATE  /* isry.couns.constt.medscsnntabrd.mapper.BbseumListMapper.updateCrisisBoard : 이음-e 위기유형등록 */
        AYA110  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       '03'                   /*  게시판유형구분코드  */

UPDATE  /* isry.couns.constt.medscsnntabrd.mapper.BbseumListMapper.updateCrisisPerson : 이음-e 위기유형등록 */
        AYA120  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   CLIENA_ID               =       #{CLIENA_ID}
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO       =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD      =       '03'                   /*  게시판유형구분코드  */

UPDATE  /* isry.couns.constt.medscsnntabrd.mapper.BbscttListMapper.updateMemo : 비밀게시판 메모수정 */
        AYA160
SET
        MEMO_NM                 =       #{MEMO_NM}
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND BBSCTT_ESNTAL_NO        =       #{BBSCTT_ESNTAL_NO}
    AND BBSCTT_TYPE_SE_CD       =       '03'

mapper.select:
/* isry.couns.constt.medscsnntabrd.mapper.eumContentList : 이음템플릿이력목록 */
select CNCT_NTABRD_CTGRYB_SE_CD , SESN_MNG_NO , CNCT_PAGE_SN , CHG_AFTR_CNTT_CN , DEL_YN , FRST_RGTR_ID , TO_CHAR(FRST_REG_DT, 'YYYYMMDD') FRST_REG_DT , LAST_MDFR_ID , TO_CHAR(LAST_MDFCN_DT, 'YYYYMMDD') LAST_MDFCN_DT from AYE230 where 1=1
AND CNCT_NTABRD_CTGRYB_SE_CD = #{CNCT_NTABRD_CTGRYB_SE_CD}
AND SESN_MNG_NO = #{SESN_MNG_NO}
AND CNCT_PAGE_SN = #{CNCT_PAGE_SN}
order by FRST_REG_DT desc

mapper.insert:

        /* isry.couns.constt.medscsnntabrd.mapper.insertAYE230 : 이음템플릿이력저장 */

        insert into AYE230
        (
	        CNCT_NTABRD_CTGRYB_SE_CD
			, SESN_MNG_NO
			, CNCT_PAGE_SN
			, INDEX_SN
			, CHG_BFE_CNTT_CN
			, CHG_AFTR_CNTT_CN
			, DEL_YN
			, FRST_RGTR_ID
			, FRST_REG_DT
			, LAST_MDFR_ID
			, LAST_MDFCN_DT
        ) values (
	        #{CNCT_NTABRD_CTGRYB_SE_CD}
			, #{SESN_MNG_NO}
			, #{CNCT_PAGE_SN}
			, AYE230_SQ01.nextval
			, (select CHG_AFTR_CNTT_CN from AYE200
				 where CNCT_NTABRD_CTGRYB_SE_CD = #{CNCT_NTABRD_CTGRYB_SE_CD}
				 and SESN_MNG_NO = #{SESN_MNG_NO}
				 and CNCT_PAGE_SN = #{CNCT_PAGE_SN})
			, #{CHG_AFTR_CNTT_CN}
			, 'N'
			, #{FRST_RGTR_ID}
			, SYSDATE
			, #{LAST_MDFR_ID}
			, SYSDATE
        )

mapper.update:

/* isry.couns.constt.medscsnntabrd.mapper.updateAYE200 : 이음템플릿저장 */

update AYE200
set CHG_AFTR_CNTT_CN = #{CHG_AFTR_CNTT_CN}
, LAST_MDFR_ID = #{LAST_MDFR_ID}
, LAST_MDFCN_DT = SYSDATE
where CNCT_NTABRD_CTGRYB_SE_CD = #{CNCT_NTABRD_CTGRYB_SE_CD}
and SESN_MNG_NO = #{SESN_MNG_NO}
and CNCT_PAGE_SN = #{CNCT_PAGE_SN}


update  AYE120   /* isry.couns.constt.medscsnntabrd.mapper.updateAYE200 : 이음템플릿저장 */
set 
        EML_SNDNG_YN        =       'Y'
    ,   LAST_MDFR_ID        =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT       =       SYSDATE
where   BBSCTT_ESNTAL_NO    =       #{BBSCTT_ESNTAL_NO}
    and BBSCTT_TYPE_SE_CD   =       #{BBSCTT_TYPE_SE_CD}
    and RETE_ESNTAL_NO      =       #{RETE_ESNTAL_NO}
